// spec: specs/ssr-seo-public.md (1.1)
// seed: tests/seed.spec.ts
// Прод, только чтение: сырой HTML через request API, без браузера и JS.
import { test, expect } from '@playwright/test';
import { readSitemap, rawHtml, rootHtml, seoBody, h1s, links, jsonLd, nodesOfType, textOf } from './ssr-seo.helpers';

test.describe('SSR и SEO публичных страниц — SSR-контент', () => {
  test('Главная: в сыром HTML SSR-блок с h1, текстом, ссылками на все категории и JSON-LD Organization+WebSite #b3dc2e @desktop @prod-safe', async ({ request }) => {
    const sm = await readSitemap(request);
    expect(sm.categories.length, 'категории в sitemap').toBeGreaterThan(0);

    const { status, html } = await rawHtml(request, '/');
    expect(status).toBe(200);
    const root = rootHtml(html) ?? '';
    const seo = seoBody(root);
    expect(seo, 'в #root есть [data-seo-body]').toBeTruthy();
    expect(seo!.attr).toBe('/');

    expect(h1s(seo!.html)).toEqual(['Biz4Sale – זירת העסקים של ישראל']);
    const paragraphs = [...seo!.html.matchAll(/<p\b[^>]*>([\s\S]*?)<\/p>/gi)].map((m) => textOf(m[1])).filter(Boolean);
    expect(paragraphs.length, 'есть абзац текста').toBeGreaterThan(0);

    const catLinks = new Set(
      links(seo!.html)
        .map((l) => new URL(l.href, 'https://www.biz4sale.co.il'))
        .filter((u) => u.pathname === '/search' && u.searchParams.get('category'))
        .map((u) => u.searchParams.get('category')!),
    );
    expect([...catLinks].sort(), 'ссылки на категории = категории sitemap').toEqual([...sm.categories].sort());

    const ld = jsonLd(html);
    expect(ld.errors, 'JSON-LD парсится').toEqual([]);
    expect(nodesOfType(ld, 'Organization').length, 'Organization').toBeGreaterThan(0);
    expect(nodesOfType(ld, 'WebSite').length, 'WebSite').toBeGreaterThan(0);
  });
});
